solucao.css/style.css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  font-family: Georgia, serif;
  background-color: #fff8f0;
  color: #3b2a20;
}
.topo {
  padding: 20px 40px;
  text-align: center;
  background-color: #b23a48;
}
.topo h1 {
  color: #ffffff;
}
.menu {
  list-style: none;
  margin-top: 10px;
}
.menu li {
  display: inline-block;
  margin: 0 12px;
}
.menu a {
  color: #ffffff;
  text-decoration: none;
  font-weight: bold;
}
.container {
  width: 900px;
  margin: 0 auto;
  padding: 30px 0;
}
h2 {
  margin-bottom: 16px;
  color: #b23a48;
}
.pratos {
  list-style: none;
}
.prato {
  padding: 16px;
  border: 2px solid #e0c9a6;
  margin-bottom: 20px;
  border-radius: 12px;
  background-color: #ffffff;
}
.prato img {
  width: 240px;
  display: block;
  margin-bottom: 10px;
}
.preco {
  font-weight: bold;
  color: #2e7d32;
}
.bebidas dt {
  font-weight: bold;
  margin-top: 10px;
}
.bebidas dd {
  margin-left: 20px;
}
.rodape {
  margin-top: 30px;
  padding: 24px;
  text-align: center;
  background-color: #3b2a20;
  color: #ffffff;
}
.rodape a {
  color: #f5c26b;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  font-family: Arial, sans-serif;
  background-color: #eef2f7;
  color: #1a2233;
}
.caixa {
  width: 480px;
  margin: 40px auto;
  padding: 24px;
  background-color: #ffffff;
  border-radius: 12px;
}
h1 {
  margin-bottom: 8px;
}
form {
  margin-top: 16px;
}
.campo {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}
label {
  font-weight: bold;
}
input, select, textarea {
  padding: 8px;
  border: 1px solid #c9d3e6;
  border-radius: 6px;
}
.turnos {
  display: flex;
  gap: 16px;
  border: none;
  margin-bottom: 16px;
}
.turnos label, .aceite label {
  font-weight: normal;
}
.aceite {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}
#inscricao button {
  width: 100%;
  padding: 12px;
  border: none;
  border-radius: 6px;
  background-color: #2459c7;
  color: #ffffff;
}
button:hover {
  background-color: #14213d;
}
